import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·8","description":"易小帖 - 卷三·8","frontmatter":{"title":"卷三·8","description":"易小帖 - 卷三·8"},"headers":[],"relativePath":"classics/yixiaotie/076.md","filePath":"classics/yixiaotie/076.md"}'),o={name:"classics/yixiaotie/076.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·8",tabindex:"-1"},[r("卷三·8 "),e("a",{class:"header-anchor",href:"#卷三·8","aria-label":"Permalink to “卷三·8”"},"​")],-1),e("p",null,"陳氏所傳河圖五十五數，洛書四十五數，《本義》襲之，載《周易》之首。然當時實不明指為孰圖孰書，故李溉親受之，陳氏不再傳，而劉牧作《鈎隱圖》易解，即已顛倒其說，指五十五數者為書，四十五數者為圖。賴阮天隱作偽《關朗傳》以闢之，然後南宋諸儒翕然變名，如今所傳本，然究有不盡變者。朱子發作圖註，聶麟作圖解，魏華父張文饒作易義，朱日華作《三易備遺》，李蒙齋作《學易記》，皆尚顛倒，如劉長民說。然則為圖為書，在創授家且無成軌，後此者將安宗之。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
